function parseHex(hex) {
	const clean = hex.replace("#", "");
	return [
		parseInt(clean.slice(0, 2), 16),
		parseInt(clean.slice(2, 4), 16),
		parseInt(clean.slice(4, 6), 16)
	];
}
function mixHex(a, b, t) {
	const clamped = Math.max(0, Math.min(1, t));
	const [r1, g1, b1] = parseHex(a);
	const [r2, g2, b2] = parseHex(b);
	const r = Math.round(r1 + (r2 - r1) * clamped);
	const g = Math.round(g1 + (g2 - g1) * clamped);
	const bl = Math.round(b1 + (b2 - b1) * clamped);
	return `#${r.toString(16).padStart(2, "0")}${g.toString(16).padStart(2, "0")}${bl.toString(16).padStart(2, "0")}`;
}
function getLiquidColor(tea, steepSeconds, toppings) {
	const norm = Math.min(1, steepSeconds / 8);
	let base;
	if (norm < .2) base = mixHex("#E8E6DF", tea.lightColor, norm / .2);
	else if (norm < .65) base = mixHex(tea.lightColor, tea.richColor, (norm - .2) / .45);
	else base = mixHex(tea.richColor, tea.deepColor, (norm - .65) / .35);
	if (toppings.includes("lemon") && tea.lemonColor) base = mixHex(base, tea.lemonColor, .85);
	if (toppings.includes("strawberry")) base = mixHex(base, "#DE798D", .42);
	if (toppings.includes("brown-sugar")) base = mixHex(base, "#A86B38", .38);
	if (toppings.includes("cinnamon")) base = mixHex(base, "#C86D2F", .45);
	if (toppings.includes("milk")) {
		const targetMilk = tea.milkColor ?? mixHex(base, "#F4EDE1", .45);
		base = mixHex(base, targetMilk, .72);
	}
	if (toppings.includes("milk-foam")) base = mixHex(base, "#F6F1E6", .25);
	if (toppings.includes("ice")) base = mixHex(base, "#FFFFFF", .08);
	return base;
}
function getStrengthLabel(tea, steepSeconds) {
	if (steepSeconds < tea.idealSteepMin) return "อ่อนละมุน";
	if (steepSeconds <= tea.idealSteepMax) return "กลมกล่อมลงตัว";
	return "เข้มข้นถึงใจ";
}
