// src/utils/fullscreen.ts
function isFullscreenActive() {
	if (typeof document === "undefined") return false;
	const doc = document;
	return Boolean(doc.fullscreenElement || doc.webkitFullscreenElement);
}
async function requestAppFullscreen() {
	if (typeof document === "undefined") return false;
	if (isFullscreenActive()) return true;
	const el = document.documentElement;
	try {
		if (el.requestFullscreen) try {
			await el.requestFullscreen({ navigationUI: "hide" });
		} catch {
			await el.requestFullscreen();
		}
		else if (el.webkitRequestFullscreen) await Promise.resolve(el.webkitRequestFullscreen());
		else return false;
		const orientation = screen?.orientation;
		if (orientation?.lock) orientation.lock("landscape").catch(() => {});
		return isFullscreenActive();
	} catch {
		return false;
	}
}
async function exitAppFullscreen() {
	if (typeof document === "undefined") return;
	if (!isFullscreenActive()) return;
	const doc = document;
	try {
		if (doc.exitFullscreen) await doc.exitFullscreen();
		else if (doc.webkitExitFullscreen) await Promise.resolve(doc.webkitExitFullscreen());
	} catch {}
}
async function toggleAppFullscreen() {
	if (isFullscreenActive()) {
		await exitAppFullscreen();
		return false;
	}
	return requestAppFullscreen();
}
function subscribeFullscreenChange(callback) {
	if (typeof document === "undefined") return () => {};
	const handler = () => {
		callback(isFullscreenActive());
	};
	document.addEventListener("fullscreenchange", handler);
	document.addEventListener("webkitfullscreenchange", handler);
	return () => {
		document.removeEventListener("fullscreenchange", handler);
		document.removeEventListener("webkitfullscreenchange", handler);
	};
}
